param([string]$Path='docs/openapi-v13-canonical.json',[string]$EntryPoint='backend/SanSo.Api.V6/ProgramCanonicalV13.cs')
$ErrorActionPreference='Stop';$raw=Get-Content -LiteralPath $Path -Raw -Encoding UTF8;$source=Get-Content -LiteralPath $EntryPoint -Raw -Encoding UTF8;$d=$raw|ConvertFrom-Json
if($d.info.version-ne'0.13.0-pilot'-or$d.'x-sanso-canonical-entrypoint'-ne$EntryPoint){throw 'OPENAPI_V13_HEADER_INVALID'};if($raw.Contains('SÄ‚')){throw 'MOJIBAKE_DETECTED'}
$routes=@('/health','/api/auth/login','/api/imports/preview','/api/imports/confirm','/api/imports/settlements','/api/imports/settlements/confirm','/api/dashboard','/api/orders','/api/reconciliations/current','/api/reconciliations/{runId}','/api/inventory/{sku}','/api/inventory/{sku}/reserve','/api/inventory/{sku}/release','/api/notifications','/api/notifications/{id}/acknowledge','/api/onboarding','/api/onboarding/business-profile','/api/onboarding/data-source','/api/onboarding/backfill','/api/onboarding/sku-mapping','/api/onboarding/opening-balances','/api/onboarding/disclaimer','/api/onboarding/first-reconciliation','/api/reports','/api/reports/exports','/api/reports/exports/{id}/confirm','/api/reports/exports/{id}','/api/reports/exports/{id}/download')
foreach($route in $routes){if($null-eq$d.paths.$route){throw "ROUTE_MISSING:$route"};if($route-ne'/api/auth/login'-and-not$source.Contains($route)){throw "ROUTE_NOT_IN_SOURCE:$route"}}
if($null-ne$d.paths.'/api/imports/settlements/direct'){throw 'DEVELOPMENT_ROUTE_EXPOSED'}
$refs=[regex]::Matches($raw,'"\$ref"\s*:\s*"#/components/([^/]+)/([^"/]+)"');foreach($m in $refs){if($null-eq$d.components.($m.Groups[1].Value).($m.Groups[2].Value)){throw "BROKEN_REF:$($m.Value)"}}
"OPENAPI_V13_VERIFIED paths=$(@($d.paths.PSObject.Properties).Count) refs=$($refs.Count) routes=$($routes.Count) utf8=true directPublic=false"
